fn linear(c: u32, shift: u32) -> f64 { let v = ((c >> shift) & 255) as f64 / 255.0; if v <= 0.04045 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) } }
fn luminance(c: u32) -> f64 { 0.2126*linear(c,24) + 0.7152*linear(c,16) + 0.0722*linear(c,8) }
fn contrast(a: u32,b: u32) -> f64 { let (x,y)=(luminance(a),luminance(b)); (x.max(y)+0.05)/(x.min(y)+0.05) }
fn accent_candidate(source: u32, lighten: bool, percent: u32) -> u32 {
    let mut out=0; for shift in [8,16,24] { let channel=(source>>shift)&255; let target=if lighten {255} else {0}; let adjusted=(channel*(100-percent)+target*percent+50)/100; out|=adjusted<<shift; } out|255
}

pub fn theme_tokens_accented(theme: Theme, high_contrast: bool, system_accent_srgb: u32) -> Tokens {
    let mut tokens=theme_tokens(theme,high_contrast);
    if system_accent_srgb == 0 || system_accent_srgb & 255 == 0 { return tokens; }
    let required=if high_contrast {4.5} else {3.0}; let lighten=theme==Theme::Dark;
    let mut best=system_accent_srgb|255; let mut best_score=0.0;
    for amount in 0..=100 { let candidate=accent_candidate(system_accent_srgb,lighten,amount);
        let score=contrast(candidate,tokens.panel).min(contrast(candidate,tokens.panel_raised));
        if score>best_score {best=candidate;best_score=score;} if score>=required {best=candidate;break;} }
    tokens.accent=best; tokens.selection_edge=best; tokens.focus_ring=best;
    let percent=if high_contrast {20} else {14}; let mut blended=255;
    for shift in [8,16,24] { let back=(tokens.panel>>shift)&255; let front=(best>>shift)&255;
        blended|=((back*(100-percent)+front*percent+50)/100)<<shift; }
    tokens.selection_fill=blended; tokens
}

pub const fn type_scale() -> TypeScale { TypeScale { document_title_pt:14,panel_heading_pt:13,section_heading_pt:12,body_pt:13,secondary_pt:12,metadata_pt:11,geometry_pt:12,empty_heading_pt:22,geometry_monospaced:true,title_semibold:true,section_semibold:true,empty_heading_semibold:true } }
